pragma solidity ^0.8.0;

import {Test} from "forge-std/Test.sol";
import {PRIVATE_ETH_CELL} from "../src/PRIVATE_ETH_CELL.sol";

contract InvMutTest is Test {
    uint256 internal constant VALUE_CAP = 1000000000000000000000000000000;
    PRIVATE_ETH_CELL c;

    function setUp() public {
        c = new PRIVATE_ETH_CELL();
    }

    function _run(uint256 depositAmount, uint256 am) internal {
        depositAmount = bound(depositAmount, 0, 1000000000000000000000000000000);
        vm.deal(address(this), VALUE_CAP);
        vm.deal(address(c), VALUE_CAP);
        vm.assume(address(this).balance >= depositAmount);
        vm.assume(depositAmount > 0);
        vm.assume(am > 0);
        vm.assume(am <= depositAmount);
        try c.SetMinSum(depositAmount) {} catch { return; }
        try c.Deposit{value: depositAmount}() {} catch { return; }
        uint256 before;
        try c.balances(address(this)) returns (uint256 __r) { before = __r; } catch { return; }
        bool reverted;
        try c.Collect(am) { reverted = false; } catch { reverted = true; }
        uint256 afterBalance;
        try c.balances(address(this)) returns (uint256 __r) { afterBalance = __r; } catch { return; }
        assertTrue(!reverted && before >= am && afterBalance == before - am);
    }

    function testFuzz_run(uint256 depositAmount, uint256 am) public {
        _run(depositAmount, am);
    }

    receive() external payable {}
}
